pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // keep the domain wide; assume only that _tos does not exceed a reasonable length
        vm.assume(_tos.length <= 50);

        // try the transfer call; we wrap it in a try/catch to observe whether it reverts
        bool ok = true;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            // if it does not revert, we land here; the return value is always true in these implementations
            ok = true;
        } catch {
            ok = false;
        }

        // the reference P always reverts when _tos.length == 0, and never reverts when _tos.length > 0.
        // the mutant M never reverts (always returns true).
        // Therefore, the reference rule is: the transfer call reverts iff _tos is empty.
        assertTrue((ok && _tos.length > 0) || (!ok && _tos.length == 0));
    }
}

