pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // 1. Keep domain wide: only exclude cases where tos is empty, since reference C always reverts there
        //    but we must still handle it to observe the difference. We do not vm.assume on _tos length.
        // 2. caddress must be a contract that can handle transferFrom without reverting, to ensure both versions can succeed when tos is non-empty.
        //    Deploy a helper that succeeds on transferFrom calls, and use its address as caddress.
        Helper helper = new Helper();
        address target = address(helper);
        // 3. Record whether reference C call reverts
        bool refOk;
        try c.transfer(from, target, _tos, v) returns (bool ret) {
            refOk = true;
        } catch {
            refOk = false;
        }
        // 4. The rule: reference C does not return true (i.e., refOk is false) when _tos is empty,
        //    but the mutant M would return true in that case (since it lacks the require).
        //    For the fuzzer, we assert that if reference succeeds, it returns true (which is always the case for non-empty _tos).
        //    More precisely: The reference C satisfies: IF refOk is true THEN _tos.length > 0.
        //    The mutant M violates this because it allows refOk to be true even when _tos.length == 0.
        //    However, we cannot directly call M in this test; we only observe c (reference).
        //    The property must be stated over c: c.transfer(...) does not succeed when _tos is empty.
        //    So assert: if _tos.length == 0, then !refOk.
        //    This holds for every input on reference C, and the fuzzer will find _tos.length == 0 where this assertion fails on the mutant (if we could run M).
        //    We express this as an assertion that should always be true for reference C.
        if (_tos.length == 0) {
            assertTrue(!refOk);
        } else {
            // For non-empty tos, both reference and mutant behave identically; no property violation possible.
            // We simply skip assert or use a trivial true to avoid false positives.
            assertTrue(true);
        }
    }
}

contract Helper {
    // Minimal contract that accepts any transferFrom call without reverting.
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

