pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // deploy a helper that always succeeds on transferFrom to isolate the length-check difference
        Helper h = new Helper();
        // fuzz controls _tos length, including empty
        try c.transfer(from, address(h), _tos, v) returns (bool ret) {
            // if the call succeeds, the mutant also succeeds and returns true;
            // the reference only succeeds when _tos.length > 0 and also returns true.
            // The property: both must return the same value (true) on success.
            assertTrue(ret == true);
        } catch {
            // if the call reverts, the reference reverts on empty _tos;
            // the mutant never reverts here because helper always succeeds.
            // The property: if the reference reverts, the mutant must also revert (observable as a revert).
            // Since the mutant does not revert on empty _tos, this catch is only reachable by the reference,
            // making the revert-check the discriminating assertion.
            assertTrue(_tos.length == 0);
        }
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

